// Slider + BCD toggle + pin-extension readout for the vault mechanism.
// Drives the inline #mechanism-svg generated by
// vaultkit.explainers.schematic.full_mechanism_interactive().

(function () {
  const RATIO = 5;                   // 120 / 24 — turns of spur per turn of ring
  const SPUR_PITCH_RADIUS_MM = 6.0;  // module 0.5 × 24 teeth / 2
  const SPUR_COUNT = 12;

  function ready(fn) {
    if (document.readyState !== "loading") fn();
    else document.addEventListener("DOMContentLoaded", fn);
  }

  ready(function () {
    const svg = document.getElementById("mechanism-svg");
    const slider = document.getElementById("ring-angle-slider");
    const angleReadout = document.getElementById("ring-angle-readout");
    const pinReadout = document.getElementById("pin-readout");
    const bcdToggle = document.getElementById("bcd-toggle");
    if (!svg || !slider) return;  // nothing wired up; page is read-only

    const ring = svg.querySelector("#ring");
    const spurs = {
      math: [], measured: [],
    };
    const rackpins = {
      math: [], measured: [],
    };
    for (let i = 0; i < SPUR_COUNT; i++) {
      for (const layer of ["math", "measured"]) {
        spurs[layer].push(svg.querySelector(`#spur-${i}-${layer}`));
        rackpins[layer].push(svg.querySelector(`#rackpin-${i}-${layer}`));
      }
    }

    function applyTheta(thetaDeg) {
      // Ring rotates by +theta.
      ring.setAttribute("transform", `rotate(${thetaDeg})`);

      // Spur rotation = -theta * ratio (counter, in the ring's frame).
      const spurAngle = -thetaDeg * RATIO;

      // Rack/pin translation: Δr = θ_rad × spur_pitch_radius.
      // Cap to a reasonable visual max so extreme slider values don't fly
      // the pins off-screen.
      const thetaRad = (thetaDeg * Math.PI) / 180;
      const dr = thetaRad * SPUR_PITCH_RADIUS_MM;
      const drClamped = Math.max(-8, Math.min(8, dr));

      for (const layer of ["math", "measured"]) {
        for (let i = 0; i < SPUR_COUNT; i++) {
          const s = spurs[layer][i];
          const rp = rackpins[layer][i];
          if (s) s.setAttribute("transform", `rotate(${spurAngle})`);
          if (rp) rp.setAttribute("transform", `translate(${drClamped} 0)`);
        }
      }

      if (angleReadout) angleReadout.textContent = thetaDeg.toFixed(1) + "°";
      if (pinReadout) pinReadout.textContent = Math.abs(drClamped).toFixed(2) + " mm";
    }

    slider.addEventListener("input", function () {
      applyTheta(parseFloat(slider.value));
    });

    if (bcdToggle) {
      function applyBcd() {
        // Use explicit "inline"/"none" — setting style.display to ""
        // removes the inline override but leaves the SVG's CSS rule
        // `.layer-measured { display: none }` in effect, hiding the
        // measured layer when we want to show it.
        const showMeasured = bcdToggle.checked;
        svg.querySelectorAll(".layer-math").forEach(function (el) {
          el.style.display = showMeasured ? "none" : "inline";
        });
        svg.querySelectorAll(".layer-measured").forEach(function (el) {
          el.style.display = showMeasured ? "inline" : "none";
        });
      }
      bcdToggle.addEventListener("change", applyBcd);
      applyBcd();
    }

    // Initial render in case the slider didn't fire input on load.
    applyTheta(parseFloat(slider.value));
  });
})();
